-- Revisa que los nodos funcionen corretamente--
SELECT (SELECT COUNT(*) FROM Cliente) + (SELECT COUNT(*) FROM Cuenta) + (SELECT COUNT(*) FROM Dispositivo)
     + (SELECT COUNT(*) FROM IP) + (SELECT COUNT(*) FROM Comercio) AS nodos,
       (SELECT COUNT(*) FROM Posee) + (SELECT COUNT(*) FROM Usa_Dispositivo) + (SELECT COUNT(*) FROM Conecta_Desde)
     + (SELECT COUNT(*) FROM Transfiere_A) + (SELECT COUNT(*) FROM Paga_En) AS relaciones;
